/** Total number of blocks in a program (containers count as one block each). */
export function countBlocks(program: Program): number {
  let n = 0;
  for (const b of program) {
    n += 1;
    if (b.kind === "repeat") n += countBlocks(b.body);
    if (b.kind === "if") n += countBlocks(b.then) + countBlocks(b.else);
  }
  return n;
}

export function programDepth(program: Program): number {
  let d = 0;
  for (const b of program) {
    if (b.kind === "repeat") d = Math.max(d, 1 + programDepth(b.body));
    else if (b.kind === "if") d = Math.max(d, 1 + programDepth(b.then), 1 + programDepth(b.else));
  }
  return d;
}

