"import type { Concept } from "./types";

/* ------------------------------ Stars & score ------------------------------ */

export type StarInput = {
  blocksUsed: number;
  optimalBlocks: number;
  /** Failed runs in the current play session before this success. */
  failedAttempts: number;
  /** Highest Bibi hint tier used in this play session (0 = no hints). */
  maxHintTier: number;
  /** Number of Bibi hints used in this play session. */
  hintsUsed: number;
};

/**
 * FR-MISI-06 / FR-AI-07: 1–3 stars based on block efficiency, attempts, and
 * proportional hint usage. Never below 1 star (NFR-UX-04: no punishing screens).
 */
export function starPenalty(input: StarInput): number {
  const over = input.blocksUsed - input.optimalBlocks;
  const efficiency = over <= 0 ? 0 : over <= 2 ? 0.5 : 1;
  const attempts = input.failedAttempts >= 6 ? 1 : input.failedAttempts >= 3 ? 0.5 : 0;
  const tierPenalty = [0, 0.25, 0.5, 1][Math.min(3, Math.max(0, input.maxHintTier))];
  const extraHints = Math.max(0, input.hintsUsed - 3) * 0.25;
  const hints = Math.min(1.5, tierPenalty + extraHints);
  return efficiency + attempts + hints;
}

export function computeStars(input: StarInput): 1 | 2 | 3 {
  const raw = Math.round(3 - starPenalty(input));
  return Math.min(3, Math.max(1, raw)) as 1 | 2 | 3;
}

export function computeScore(input: StarInput, stars: number): number {
  const efficientBonus = input.blocksUsed <= input.optimalBlocks ? 50 : 0;
  const noHintBonus = input.hintsUsed === 0 ? 50 : 0;
  return stars * 100 + efficientBonus + noHintBonus;
}

